  console.log(`🌤️ 已同步 Sky: enabled=${skyEnabled.value}, preset=${skyPreset.value}, elevation=${skyParams.elevation}°, azimuth=${skyParams.azimuth}°`);
}

// 🔥 检测当前天空参数是否匹配某个预设
function detectSkyPreset(): string {
  for (const [presetName, preset] of Object.entries(skyPresets)) {
    if (
      Math.abs(skyParams.turbidity - preset.turbidity) < 0.1 &&
      Math.abs(skyParams.rayleigh - preset.rayleigh) < 0.1 &&
      Math.abs(skyParams.mieCoefficient - preset.mieCoefficient) < 0.001 &&
      Math.abs(skyParams.mieDirectionalG - preset.mieDirectionalG) < 0.01 &&
      Math.abs(skyParams.elevation - preset.elevation) < 1 &&
      Math.abs(skyParams.azimuth - preset.azimuth) < 5
    ) {
      return presetName;
    }
  }
  return 'custom';
}

// 🔥 天空预设变化处理
