function getFpsClass(fps: number): string {
  if (fps >= 50) return 'fps-good';
  if (fps >= 30) return 'fps-ok';
  return 'fps-bad';
}

function getVelocityClass(velocity: number): string {
  if (velocity > 1) return 'velocity-up';
  if (velocity < -1) return 'velocity-down';
  return 'velocity-stable';
}

function formatVector3(vec: { x: number; y: number; z: number } | null): string {
  if (!vec) return 'N/A';
  return `(${vec.x.toFixed(2)}, ${vec.y.toFixed(2)}, ${vec.z.toFixed(2)})`;
}

function formatRotation(rot: { x: number; y: number; z: number } | null): string {
  if (!rot) return 'N/A';
  return `(${rot.x}°, ${rot.y}°, ${rot.z}°)`;
}

/**
 * 复制角色的 Transform（渲染坐标版）到剪贴板
 *
 * position 字段语义 = rebase 后的渲染坐标（= 物理世界中角色实际所处坐标）
 * 如需配置文件 module.transform.position 的"原始世界坐标"，请用「复制角色（偏移前）Transform」按钮
 */
async function copyCharacterTransform() {
  const position = physicsInfo.characterPosition;
  if (!position) {
    alert('无法获取角色位置');
    return;
  }

  const rotation = physicsInfo.characterRotation || { x: 0, y: 0, z: 0 };
  const round2 = (/** @type {number} */ v) => Math.round(v * 100) / 100;

  const transform = {
    position: {
      x: round2(position.x),
      y: round2(position.y),
      z: round2(position.z),
    },
    rotation,
  };

  const transformStr = JSON.stringify(transform, null, 2);

  try {
    await navigator.clipboard.writeText(transformStr);
    console.log('📋 复制的 Transform:', transformStr);
  } catch (err) {
    console.error('复制失败:', err);
  }
}

/**
 * 复制角色的 Transform（偏移前 / 原始世界坐标版）到剪贴板
 *
 * position 字段语义 = 渲染坐标 + worldOffset = 配置文件 module.transform.position 用的坐标系
 * 直接贴回模块配置即可，不需要再手动加偏移量。
 * worldOffset 全 0（rebase 未触发 / debugManager 缺失）时，等价于复制渲染坐标。
 */
async function copyCharacterRawTransform() {
  const position = physicsInfo.characterPosition;
  if (!position) {
    alert('无法获取角色位置');
    return;
  }

  const rotation = physicsInfo.characterRotation || { x: 0, y: 0, z: 0 };
  const worldOffset = props.debugManager?.getWorldOffset?.() ?? { x: 0, y: 0, z: 0 };
  const round2 = (/** @type {number} */ v) => Math.round(v * 100) / 100;

  const renderPosition = {
    x: round2(position.x),
    y: round2(position.y),
    z: round2(position.z),
  };
  const realWorldPosition = {
    x: round2(position.x + worldOffset.x),
    y: round2(position.y + worldOffset.y),
    z: round2(position.z + worldOffset.z),
  };

  const transform = {
    position: realWorldPosition,
    rotation,
  };

  const transformStr = JSON.stringify(transform, null, 2);

  try {
    await navigator.clipboard.writeText(transformStr);
    console.log('📋 复制的 Transform (偏移前):', transformStr);
    console.log('   ├─ 📍 原始世界坐标 (position):', realWorldPosition);
    console.log('   ├─ 🎬 渲染坐标 (renderPosition):', renderPosition);
    console.log('   └─ ↔️ worldOffset:', worldOffset);
  } catch (err) {
    console.error('复制失败:', err);
  }
}

function updateStats() {
  if (props.debugManager) {
    const stats = props.debugManager.getPerformanceStats();
    Object.assign(performanceStats, stats);

    const physics = props.debugManager.getPhysicsInfo();
    if (physics) {
      Object.assign(physicsInfo, physics);
    }

    // 同步调试配置状态
    Object.assign(debugConfig, props.debugManager.config);
  }

  // 更新NPC列表
  updateNPCList();
}

// Lifecycle
onMounted(() => {
  // 每秒更新统计信息
  updateInterval = setInterval(updateStats, 1000);

  // 从 physicsWorldManager 获取悬崖检测配置的实际值
  if (props.physicsWorldManager) {
    const actualConfig = props.physicsWorldManager.getCliffDetectionConfig();
    if (actualConfig) {
      cliffDetectionConfig.enabled = actualConfig.enabled ?? true;
      cliffDetectionConfig.checkDistance = actualConfig.checkDistance ?? 0.35;
      cliffDetectionConfig.maxFallDistance = actualConfig.maxFallDistance ?? 3.0;
      cliffDetectionConfig.safetyMargin = actualConfig.safetyMargin ?? 0.1;
    }
  }

  // 从 sceneManager 获取 HDRI 配置并同步到面板
  initHDRIFromConfig();

  // 从 sceneManager 获取 ToneMapping 配置并同步到面板
  initToneMappingFromConfig();

  // 监听键盘事件
  const handleKeyDown = (event: KeyboardEvent) => {
    // F1 键切换debug面板
    if (event.key === 'F1') {
      event.preventDefault();
      togglePanel();
    }

    // F2 键切换碰撞体可视化（走互斥逻辑：开启时会自动关闭"显示碰撞体面"）
    if (event.key === 'F2') {
      event.preventDefault();
      debugConfig.showColliders = !debugConfig.showColliders;
      onColliderVisualToggle('showColliders');
    }

    // F3 键切换线框模式
    if (event.key === 'F3') {
      event.preventDefault();
      debugConfig.wireframeMode = !debugConfig.wireframeMode;
      onConfigChange();
    }
  };

  document.addEventListener('keydown', handleKeyDown);

  // 清理函数
  onUnmounted(() => {
    if (updateInterval) {
      clearInterval(updateInterval);
    }
    document.removeEventListener('keydown', handleKeyDown);
  });
});

// 监听 physicsWorldManager 变化，同步悬崖检测配置
watch(
  () => props.physicsWorldManager,
  (newManager) => {
    if (newManager) {
      const actualConfig = newManager.getCliffDetectionConfig();
      if (actualConfig) {
        cliffDetectionConfig.enabled = actualConfig.enabled ?? true;
        cliffDetectionConfig.checkDistance = actualConfig.checkDistance ?? 0.35;
        cliffDetectionConfig.maxFallDistance = actualConfig.maxFallDistance ?? 3.0;
        cliffDetectionConfig.safetyMargin = actualConfig.safetyMargin ?? 0.1;
      }
    }
  },
  { immediate: true },
);

// 监听 sceneManager 变化，同步 HDRI 配置、ToneMapping 配置和 Sky 配置
watch(
  () => props.sceneManager,
  (newManager) => {
    if (newManager) {
      // 使用 onSceneReady 回调，确保场景配置已经加载完成
      newManager.onSceneReady(() => {
        initHDRIFromConfig();
        initToneMappingFromConfig();
        initSkyFromConfig();
        initCloudFromConfig();
      });
    }
  },
  { immediate: true },
);
</script>

