/**
 * @changelog
 *   v1.0.0 - 写法 A：纯 inject 范式，对齐 thirdroom 的 useMainThreadContext 写法
 *            （src/ui/hooks/useMainThread.ts）。
 *            ─ React: createContext + useContext + Provider + 抛错守卫
 *            ─ Vue:  Symbol InjectionKey + provide + inject + 抛错守卫
 *
 *            为什么需要 Ref 包裹：viewerSDK.getSceneManager()?.ctx 在 onMounted 异步
 *            await viewerSDK.init(...) 完成之后才有值；用 Ref 包裹后，子组件 inject
 *            到的是同一个 Ref 引用，ctx 就绪后所有消费者自动响应。
 *
 *            为什么提供 useGameContextGetter：viewer-sdk 的 ECS 模块 API 形如
 *            hdriModule.setEnvironmentIntensity(ctx, v)，是命令式而非响应式调用，
 *            composable（useHdriParams 等）需要在 watch / event handler 内"按需取
 *            最新 ctx"，因此暴露 () => ctx 的 getter 闭包，避免在每个 composable
 *            内手写 inject + .value 拆包。
 *            REQ: viewer-sdk-light-static-to-instance（写法 A）
 * /@changelog
 *
 * @author fancylin
 */
import { inject, provide, type InjectionKey, type Ref } from 'vue';
import type { GameContext } from '@tencent/viewer-sdk';

/**
 * GameContext 的注入 key。
 * 值为 Ref<GameContext | undefined>：viewerSDK 异步初始化后再赋值，初始为 undefined。
 */
export const GameContextKey: InjectionKey<Ref<GameContext | undefined>> = Symbol('GameContext');

/**
 * 在父组件（SceneViewer.vue）setup 顶层调用，向后代提供 GameContext Ref。
 *
 * 用法：
 * ```ts
 * const gameCtxRef = ref<GameContext | undefined>(undefined);
 * provideGameContext(gameCtxRef);
 * onMounted(async () => {
 *   await viewerSDK.init(...);
 *   gameCtxRef.value = viewerSDK.getSceneManager()?.ctx;
 * });
 * ```
 */
export function provideGameContext(ctxRef: Ref<GameContext | undefined>): void {
  provide(GameContextKey, ctxRef);
}

/**
 * 在子组件 setup 顶层调用，inject GameContext Ref。
 * 找不到 provider 时抛错（对齐 thirdroom useMainThreadContext 的硬守卫语义）。
 *
 * 注意：返回的是 Ref 而非 GameContext 本身，使用时需 .value 拆包；
 * 多数场景下应改用 useGameContextGetter() 获得 () => ctx 闭包。
 */
export function useGameContext(): Ref<GameContext | undefined> {
  const ctxRef = inject(GameContextKey);
  if (!ctxRef) {
    throw new Error(
      '[useGameContext] GameContext has not been provided. Make sure an ancestor component calls provideGameContext(ctxRef) in its setup.',
    );
  }
  return ctxRef;
}

/**
 * 返回一个无参 getter：调用时返回当前最新的 GameContext（可能为 undefined，因为
 * viewerSDK 异步初始化未完成时 ctx 还不存在）。
 *
 * 适用于命令式调用场景（事件回调、watch 回调内向 viewer-sdk 模块 API 透传 ctx）。
 *
 * 用法：
 * ```ts
 * const getCtx = useGameContextGetter();
 * const { hdriParams } = useHdriParams(getCtx);
 * ```
 */
export function useGameContextGetter(): () => GameContext | undefined {
  const ctxRef = useGameContext();
  return () => ctxRef.value;
}
